package com.lumina.tv.core

/** One caption track a video offers. [label] is what the menu shows ("English", "Hindi (auto-generated)"). */
data class SubtitleOption(
    val url: String,
    val language: String,
    val label: String,
    val mimeType: String,
    val autoGenerated: Boolean = false,
)

/** The rules for which caption tracks are offered, in what order, and which one starts selected. Pure, so they are tested. */
object SubtitleRules {
    /** A video can list dozens of caption tracks; a menu of fifty is no use from a sofa. */
    const val MAX = 12

    /**
     * The menu order: the language the person last chose first, then English, then everything else A to Z; within a
     * language, written captions before auto-generated ones. Repeats of the same language and kind are dropped, and the
     * list is capped at [MAX].
     */
    fun order(options: List<SubtitleOption>, preferredLanguage: String?): List<SubtitleOption> {
        fun rank(o: SubtitleOption) = when {
            preferredLanguage != null && sameLanguage(o.language, preferredLanguage) -> 0
            sameLanguage(o.language, "en") -> 1
            else -> 2
        }
        return options
            .filter { it.url.isNotBlank() }
            .distinctBy { baseLanguage(it.language) to it.autoGenerated }
            .sortedWith(compareBy<SubtitleOption> { rank(it) }.thenBy { if (rank(it) == 2) it.label.lowercase() else "" }.thenBy { it.autoGenerated })
            .take(MAX)
    }

    /** Index of the first track in [ordered] in the wanted language, or -1 (captions off) when none is. */
    fun initialIndex(ordered: List<SubtitleOption>, wantedLanguage: String?): Int =
        if (wantedLanguage == null) -1 else ordered.indexOfFirst { sameLanguage(it.language, wantedLanguage) }

    fun sameLanguage(a: String, b: String) = baseLanguage(a) == baseLanguage(b)

    /** "en-US" and "en" are the same language here. */
    fun baseLanguage(tag: String) = tag.substringBefore('-').substringBefore('_').lowercase()

    /** "English" or "English (auto-generated)": what the menu shows. */
    fun labelFor(displayName: String, language: String, autoGenerated: Boolean): String {
        val name = displayName.ifBlank { language.ifBlank { "Unknown" } }
        return if (autoGenerated) "$name (auto-generated)" else name
    }
}
